INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('50anos', 'published', '2026-07-08', 'club', 3, NULL, NULL, '50', 'Years of the Cape Verde Championship', 'Fifty years of the Cape Verde Championship — and Sal Rei on the roll of honour', NULL, '<p class="lead">The trophy lifted at this season’s national final carried a special mark: fifty years of the Campeonato de Cabo Verde. Among the champions inscribed in that history is Sport Sal Rei Club, winners in 2003/2004.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('academy', 'published', '2026-07-05', 'academy', 3, '/assets/img/academy-player.jpg', 'center 30%', NULL, NULL, 'Formation School: 2026/27 enrolment is now open', NULL, '<p class="lead">Sal Rei’s Formation School has opened enrolment for the 2026/27 season. Around a hundred children and young players train with the club every week, and the school remains one of the foundations of the institution.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('anniversary', 'published', '2026-07-10', 'club', 4, '/assets/img/club-celebration.jpg', 'center 45%', NULL, NULL, 'Sal Rei turn 75: the anniversary programme is unveiled', 'Founded in 1951, Sport Sal Rei Club marks three-quarters of a century this season. The club has unveiled a full programme of celebrations…', '<p class="lead">Founded in 1951, Sport Sal Rei Club marks three-quarters of a century this season. The club has unveiled a full programme of celebrations that will run from August through to the anniversary date, bringing together players, members and the wider Boa Vista community.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('bubista', 'published', '2026-07-02', 'first-team', 3, NULL, NULL, '6', 'Taça Bubista titles', 'Six times Bubista: the cup that Sal Rei has made its own', NULL, '<p class="lead">No trophy appears more often in the recent history of Sport Sal Rei Club than the Taça Bubista. Six titles, the first in 2015/16 and the most recent in 2024/25, have turned the island cup into the club’s most familiar silverware.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('crest', 'published', '2026-07-04', 'club', 3, NULL, NULL, '2024', 'A new crest for Sal Rei', 'A crest for a new era: the redesign that marked a change at Sal Rei', NULL, '<p class="lead">In 2024 the club’s board made a landmark decision: to redesign the crest that Sal Rei had carried for decades. It was more than a graphic exercise — it marked the beginning of a period that has since delivered the club’s most successful seasons in years.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('finalists', 'published', '2026-07-20', 'cape-verde', 4, NULL, NULL, '0–0', 'Cape Verde held Spain · Group H', 'The one team neither World Cup finalist could beat in ninety minutes', NULL, '<p class="lead">When Argentina and Spain met in the final at the MetLife Stadium, they had one thing in common: neither had managed to beat Cape Verde inside the regulation ninety. For a nation of half a million people, it is a footnote worth framing.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('nacional', 'published', '2026-07-06', 'regional', 4, NULL, NULL, '1–0', 'Sal Rei · Semi-final, first leg', 'Boa Vista reach the national semi-finals as África Show fall on penalties', NULL, '<p class="lead">The island of Boa Vista was represented in the semi-finals of the 2025/26 Campeonato Nacional. África Show, regional champions, won the first leg at home in Sal Rei before going out to Palmeira on penalties — the side that would go on to be crowned national champions.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('tournament', 'published', '2026-07-08', 'first-team', 3, '/assets/img/matchday-arsenio-ramos.jpg', 'center 50%', NULL, NULL, 'Capitão Carlos Nascimento Tournament opens pre-season in August', NULL, '<p class="lead">Sal Rei’s pre-season begins next month with the Capitão Carlos Nascimento Tournament, held at the Estádio Municipal Arsénio Ramos. This edition carries special weight, forming part of the club’s 75th anniversary programme.</p>
INSERT INTO news (slug, status, date, category, read_min, image, image_pos, gfx_big, gfx_cap_en, title_en, excerpt_en, body_en, pull_en, facts_en) VALUES ('worldcup', 'published', '2026-07-06', 'cape-verde', 5, NULL, NULL, 'R32', 'FIFA World Cup 2026 · Round of 32', 'Cape Verde write history: the Blue Sharks reach the World Cup knockouts', NULL, '<p class="lead">On their first ever World Cup, Cape Verde went through Group H unbeaten and became the smallest nation ever to reach the knockout stage of the tournament. The run ended against Argentina in Miami — but only after the reigning champions had been taken to extra time.</p>
